<"'!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Gravity Sandbox</title>
<style>
  html, body { margin: 0; height: 100%; overflow: hidden; background: #05070f; }
  canvas { display: block; cursor: crosshair; }
  #hud {
    position: fixed; top: 12px; left: 12px; color: #9fb4d8;
    font: 13px/1.6 ui-monospace, SFMono-Regular, Menlo, monospace;
    background: rgba(8, 12, 24, .72); border: 1px solid #1e2c47;
    border-radius: 10px; padding: 10px 14px; user-select: none;
    backdrop-filter: blur(6px); max-width: 300px;
  }
  #hud b { color: #e8eefb; }
  #hud .dim { opacity: .65 }
  #stats { position: fixed; bottom: 12px; left: 12px; color: #54648a;
    font: 12px ui-monospace, Menlo, monospace; user-select: none; }
</style>
</head>
<body>
<canvas id="c"></canvas>
<div id="hud">
  <b>Gravity Sandbox</b><br>
  <b>Drag</b> — fling a planet into being<br>
  <b>S</b> — place a heavy star<br>
  <b>C</b> — clear &nbsp;·&nbsp; <b>P</b> — pause &nbsp;·&nbsp; <b>T</b> — trails<br>
  <span class="dim">Planets merge on impact. Try orbiting the star.</span>
</div>
<div id="stats"></div>
<script>
'"'use strict';
const canvas = document.getElementById('c');
const ctx = canvas.getContext('2d');
const stats = document.getElementById('stats');

let W, H;
function resize() { W = canvas.width = innerWidth; H = canvas.height = innerHeight; }
addEventListener('resize', resize);
resize();

// Twinkling starfield background
const stars = Array.from({ length: 220 }, () => ({
  x: Math.random(), y: Math.random(),
  r: Math.random() * 1.3 + .2,
  p: Math.random() * Math.PI * 2,
  s: .5 + Math.random() * 1.5
}));

const G = 1200;               // gravitational constant (tuned for fun)
const bodies = [];
let paused = false;
let showTrails = true;
let time = 0;

const PALETTE = ['#7dd3fc', '#c4b5fd', '#f9a8d4', '#fda4af', '#fdba74', '#a7f3d0', '#fde68a'];

function addBody(x, y, vx, vy, mass, color, fixed = false) {
  bodies.push({ x, y, vx, vy, mass, color, fixed,
    r: Math.cbrt(mass) * 2.2,
    trail: [] });
}

function spawnStar(x, y) {
  addBody(x, y, 0, 0, 900, '#ffd166', true);
}

// --- interaction: drag to aim, release to launch ---
let drag = null;
canvas.addEventListener('pointerdown', e => {
  drag = { x0: e.clientX, y0: e.clientY, x1: e.clientX, y1: e.clientY };
});
canvas.addEventListener('pointermove', e => {
  if (drag) { drag.x1 = e.clientX; drag.y1 = e.clientY; }
});
addEventListener('pointerup', () => {
  if ("'!drag) return;
  const vx = (drag.x1 - drag.x0) * 1.6;
  const vy = (drag.y1 - drag.y0) * 1.6;
  const mass = 2 + Math.min(20, Math.hypot(vx, vy) / 40);
  addBody(drag.x0, drag.y0, vx, vy, mass,
    PALETTE[(Math.random() * PALETTE.length) | 0]);
  drag = null;
});
addEventListener('"'keydown', e => {
  const k = e.key.toLowerCase();
  if (k === 'c') bodies.length = 0;
  if (k === 'p') paused = "'!paused;
  if (k === '"'t') showTrails = "'!showTrails;
  if (k === '"'s') {
    const p = drag || { x1: W / 2, y1: H / 2 };
    spawnStar(lastMouse.x, lastMouse.y);
  }
});
const lastMouse = { x: innerWidth / 2, y: innerHeight / 2 };
addEventListener('pointermove', e => { lastMouse.x = e.clientX; lastMouse.y = e.clientY; });

// --- physics ---
function step(dt) {
  for (let i = 0; i < bodies.length; i++) {
    const a = bodies[i];
    if (a.fixed) continue;
    for (let j = 0; j < bodies.length; j++) {
      if (i === j) continue;
      const b = bodies[j];
      const dx = b.x - a.x, dy = b.y - a.y;
      const d2 = dx * dx + dy * dy + 100;   // softening avoids singularities
      const d = Math.sqrt(d2);
      const f = G * b.mass / (d2 * d);
      a.vx += dx * f * dt;
      a.vy += dy * f * dt;
    }
    a.x += a.vx * dt;
    a.y += a.vy * dt;
    if (showTrails) {
      a.trail.push({ x: a.x, y: a.y });
      if (a.trail.length > 90) a.trail.shift();
    } else a.trail.length = 0;
  }
  // merge overlapping bodies (inelastic collision keeps momentum)
  for (let i = bodies.length - 1; i >= 0; i--) {
    for (let j = i - 1; j >= 0; j--) {
      const a = bodies[i], b = bodies[j];
      const dx = a.x - b.x, dy = a.y - b.y;
      if (dx * dx + dy * dy < (a.r + b.r) * (a.r + b.r) * .6) {
        const m = a.mass + b.mass;
        const keep = a.mass >= b.mass ? a : b;
        const gone = keep === a ? b : a;
        keep.vx = (a.vx * a.mass + b.vx * b.mass) / m;
        keep.vy = (a.vy * a.mass + b.vy * b.mass) / m;
        keep.x = (a.x * a.mass + b.x * b.mass) / m;
        keep.y = (a.y * a.mass + b.y * b.mass) / m;
        keep.mass = m;
        keep.r = Math.cbrt(m) * 2.2;
        keep.fixed = keep.fixed || gone.fixed;
        bodies.splice(bodies.indexOf(gone), 1);
        i = bodies.length; // restart scan
        break;
      }
    }
  }
  // remove bodies flung far away
  for (let i = bodies.length - 1; i >= 0; i--) {
    const b = bodies[i];
    if (b.x < -4000 || b.x > W + 4000 || b.y < -4000 || b.y > H + 4000)
      bodies.splice(i, 1);
  }
}

// --- rendering ---
function draw() {
  ctx.fillStyle = '#05070f';
  ctx.fillRect(0, 0, W, H);

  for (const s of stars) {
    const tw = .35 + .65 * Math.abs(Math.sin(time * s.s + s.p));
    ctx.globalAlpha = tw * .8;
    ctx.fillStyle = '#cfe0ff';
    ctx.beginPath();
    ctx.arc(s.x * W, s.y * H, s.r, 0, 7);
    ctx.fill();
  }
  ctx.globalAlpha = 1;

  for (const b of bodies) {
    if (b.trail.length > 1) {
      ctx.strokeStyle = b.color;
      ctx.globalAlpha = .35;
      ctx.lineWidth = 1.2;
      ctx.beginPath();
      ctx.moveTo(b.trail[0].x, b.trail[0].y);
      for (const p of b.trail) ctx.lineTo(p.x, p.y);
      ctx.stroke();
      ctx.globalAlpha = 1;
    }
    const glow = ctx.createRadialGradient(b.x, b.y, b.r * .2, b.x, b.y, b.r * 3);
    glow.addColorStop(0, b.color);
    glow.addColorStop(1, 'transparent');
    ctx.globalAlpha = b.fixed ? .5 : .22;
    ctx.fillStyle = glow;
    ctx.beginPath();
    ctx.arc(b.x, b.y, b.r * 3, 0, 7);
    ctx.fill();
    ctx.globalAlpha = 1;

    ctx.fillStyle = b.color;
    ctx.beginPath();
    ctx.arc(b.x, b.y, b.r, 0, 7);
    ctx.fill();
    if (b.fixed) {
      ctx.fillStyle = '#fff7d6';
      ctx.beginPath();
      ctx.arc(b.x, b.y, b.r * .45, 0, 7);
      ctx.fill();
    }
  }

  // aim arrow while dragging
  if (drag) {
    const { x0, y0, x1, y1 } = drag;
    ctx.strokeStyle = '#e8eefb';
    ctx.setLineDash([6, 6]);
    ctx.lineWidth = 1.5;
    ctx.beginPath();
    ctx.moveTo(x0, y0);
    ctx.lineTo(x1, y1);
    ctx.stroke();
    ctx.setLineDash([]);
    ctx.fillStyle = '#e8eefb';
    ctx.beginPath();
    ctx.arc(x0, y0, 4, 0, 7);
    ctx.fill();
  }

  stats.textContent =
    "'`${bodies.length} bodies · ${paused ? '"'paused' : 'running'} · trails "'${showTrails ? '"'on' : 'off'}"'`;
}

// seed a little solar system so it isn'"'t empty on load
spawnStar(W / 2, H / 2);
addBody(W / 2 + 180, H / 2, 0, -Math.sqrt(G * 900 / 180), 4, '#7dd3fc');
addBody(W / 2 - 300, H / 2, 0, Math.sqrt(G * 900 / 300) * .9, 6, '#f9a8d4');

let last = performance.now();
function frame(now) {
  const dt = Math.min(.033, (now - last) / 1000);
  last = now;
  if ("'!paused) {
    time += dt;
    // substep for stability at close range
    for (let i = 0; i < 4; i++) step(dt / 4);
  }
  draw();
  requestAnimationFrame(frame);
}
requestAnimationFrame(frame);
</script>
</body>
</html>
